import { SEO_TECH_ARTICLES } from "./seo-articles-tech.js";
import { SEO_DEVELOPMENT_ARTICLES } from "./seo-articles-development.js";
import { SEO_ABAYA_ARTICLES } from "./seo-articles-abaya.js";
